select refresh_rankings();

select e.name, 'https://electraindex.com/agents/' || e.slug as page,
       (select count(*) from entities x where x.type = 'agent' and x.is_published) as agents_total
  from entities e where e.type = 'agent' and e.name in ('Trengo AI Agent', 'LiveAgent AI Agents', 'Leexi', 'Talkdesk AI Agents', 'Zowie', 'Maisa Digital Workers', 'OutSystems Agent Workbench', 'Teamtailor Co-pilot', 'Knowunity (Knowie AI tutor)') order by e.name;
